        @routes.get('/api/jobs')
        async def get_jobs(request):
            """List all jobs with filtering, sorting, and pagination.

            Query parameters:
                status: Filter by status (comma-separated): pending, in_progress, completed, failed
                workflow_id: Filter by workflow ID
                sort_by: Sort field: created_at (default), execution_duration
                sort_order: Sort direction: asc, desc (default)
                limit: Max items to return (positive integer)
                offset: Items to skip (non-negative integer, default 0)
            """
            query = request.rel_url.query
            status_param = query.get('status')
            workflow_id = query.get('workflow_id')
            sort_by = query.get('sort_by', 'created_at').lower()
            sort_order = query.get('sort_order', 'desc').lower()
            status_filter = None
            if status_param:
                status_filter = [s.strip().lower() for s in status_param.split(',') if s.strip()]
                invalid_statuses = [s for s in status_filter if s not in JobStatus.ALL]
                if invalid_statuses:
                    return web.json_response({'error': f"Invalid status value(s): {', '.join(invalid_statuses)}. Valid values: {', '.join(JobStatus.ALL)}"}, status=400)
            if sort_by not in {'created_at', 'execution_duration'}:
                return web.json_response({'error': "sort_by must be 'created_at' or 'execution_duration'"}, status=400)
            if sort_order not in {'asc', 'desc'}:
                return web.json_response({'error': "sort_order must be 'asc' or 'desc'"}, status=400)
            limit = None
            if 'limit' in query:
                try:
                    limit = int(query.get('limit'))
                    if limit <= 0:
                        return web.json_response({'error': 'limit must be a positive integer'}, status=400)
                except (ValueError, TypeError):
                    return web.json_response({'error': 'limit must be an integer'}, status=400)
            offset = 0
            if 'offset' in query:
                try:
                    offset = int(query.get('offset'))
                    if offset < 0:
                        offset = 0
                except (ValueError, TypeError):
                    return web.json_response({'error': 'offset must be an integer'}, status=400)
            (running, queued) = self.prompt_queue.get_current_queue_volatile()
            history = self.prompt_queue.get_history()
            running = _remove_sensitive_from_queue(running)
            queued = _remove_sensitive_from_queue(queued)
            (jobs, total) = get_all_jobs(running, queued, history, status_filter=status_filter, workflow_id=workflow_id, sort_by=sort_by, sort_order=sort_order, limit=limit, offset=offset)
            has_more = offset + len(jobs) < total
            return web.json_response({'jobs': jobs, 'pagination': {'offset': offset, 'limit': limit, 'total': total, 'has_more': has_more}})

        @routes.get('/api/jobs/{job_id}')
        async def get_job_by_id(request):
            """Get a single job by ID."""
            job_id = request.match_info.get('job_id', None)
            if not job_id:
                return web.json_response({'error': 'job_id is required'}, status=400)
            (running, queued) = self.prompt_queue.get_current_queue_volatile()
            history = self.prompt_queue.get_history(prompt_id=job_id)
            running = _remove_sensitive_from_queue(running)
            queued = _remove_sensitive_from_queue(queued)
            job = get_job(job_id, running, queued, history)
            if job is None:
                return web.json_response({'error': 'Job not found'}, status=404)
            return web.json_response(job)

        @routes.get('/history')
        async def get_history(request):
            max_items = request.rel_url.query.get('max_items', None)
            if max_items is not None:
                max_items = int(max_items)
            offset = request.rel_url.query.get('offset', None)
            if offset is not None:
                offset = int(offset)
            else:
                offset = -1
            return web.json_response(self.prompt_queue.get_history(max_items=max_items, offset=offset))

        @routes.get('/history/{prompt_id}')
        async def get_history_prompt_id(request):
            prompt_id = request.match_info.get('prompt_id', None)
            return web.json_response(self.prompt_queue.get_history(prompt_id=prompt_id))

        @routes.get('/queue')
        async def get_queue(request):
            queue_info = {}
            current_queue = self.prompt_queue.get_current_queue_volatile()
            queue_info['queue_running'] = _remove_sensitive_from_queue(current_queue[0])
            queue_info['queue_pending'] = _remove_sensitive_from_queue(current_queue[1])
            return web.json_response(queue_info)

        @routes.post('/prompt')
        async def post_prompt(request):
            logging.info('got prompt')
            json_data = await request.json()
            json_data = self.trigger_on_prompt(json_data)
            if 'number' in json_data:
                number = float(json_data['number'])
            else:
                number = self.number
                if 'front' in json_data:
                    if json_data['front']:
                        number = -number
                self.number += 1
            if 'prompt' in json_data:
                prompt = json_data['prompt']
                prompt_id = str(json_data.get('prompt_id', uuid.uuid4()))
                partial_execution_targets = None
                if 'partial_execution_targets' in json_data:
                    partial_execution_targets = json_data['partial_execution_targets']
                self.node_replace_manager.apply_replacements(prompt)
                valid = await execution.validate_prompt(prompt_id, prompt, partial_execution_targets)
                extra_data = {}
                if 'extra_data' in json_data:
                    extra_data = json_data['extra_data']
                if 'client_id' in json_data:
                    extra_data['client_id'] = json_data['client_id']
                if valid[0]:
                    outputs_to_execute = valid[2]
                    sensitive = {}
                    for sensitive_val in execution.SENSITIVE_EXTRA_DATA_KEYS:
                        if sensitive_val in extra_data:
                            sensitive[sensitive_val] = extra_data.pop(sensitive_val)
                    extra_data['create_time'] = int(time.time() * 1000)
                    self.prompt_queue.put((number, prompt_id, prompt, extra_data, outputs_to_execute, sensitive))
                    response = {'prompt_id': prompt_id, 'number': number, 'node_errors': valid[3]}
                    return web.json_response(response)
                else:
                    logging.warning('invalid prompt: {}'.format(valid[1]))
                    return web.json_response({'error': valid[1], 'node_errors': valid[3]}, status=400)
            else:
                error = {'type': 'no_prompt', 'message': 'No prompt provided', 'details': 'No prompt provided', 'extra_info': {}}
                return web.json_response({'error': error, 'node_errors': {}}, status=400)

        @routes.post('/queue')
        async def post_queue(request):
            json_data = await request.json()
            if 'clear' in json_data:
                if json_data['clear']:
                    self.prompt_queue.wipe_queue()
            if 'delete' in json_data:
                to_delete = json_data['delete']
                for id_to_delete in to_delete:
                    delete_func = lambda a: a[1] == id_to_delete
                    self.prompt_queue.delete_queue_item(delete_func)
            return web.Response(status=200)

        @routes.post('/interrupt')
        async def post_interrupt(request):
            try:
                json_data = await request.json()
            except json.JSONDecodeError:
                json_data = {}
            prompt_id = json_data.get('prompt_id')
            if prompt_id:
                (currently_running, _) = self.prompt_queue.get_current_queue()
                should_interrupt = False
                for item in currently_running:
                    if item[1] == prompt_id:
                        logging.info(f'Interrupting prompt {prompt_id}')
                        should_interrupt = True
                        break
                if should_interrupt:
                    nodes.interrupt_processing()
                else:
                    logging.info(f'Prompt {prompt_id} is not currently running, skipping interrupt')
            else:
                logging.info('Global interrupt (no prompt_id specified)')
                nodes.interrupt_processing()
            return web.Response(status=200)

        @routes.post('/free')
        async def post_free(request):
            json_data = await request.json()
            unload_models = json_data.get('unload_models', False)
            free_memory = json_data.get('free_memory', False)
            if unload_models:
                self.prompt_queue.set_flag('unload_models', unload_models)
            if free_memory:
                self.prompt_queue.set_flag('free_memory', free_memory)
            return web.Response(status=200)

        @routes.post('/history')
        async def post_history(request):
            json_data = await request.json()
            if 'clear' in json_data:
                if json_data['clear']:
                    self.prompt_queue.wipe_history()
            if 'delete' in json_data:
                to_delete = json_data['delete']
                for id_to_delete in to_delete:
                    self.prompt_queue.delete_history_item(id_to_delete)
            return web.Response(status=200)

    async def setup(self):
        timeout = aiohttp.ClientTimeout(total=None)
        self.client_session = aiohttp.ClientSession(timeout=timeout)

    def add_routes(self):
        self.user_manager.add_routes(self.routes)
        self.model_file_manager.add_routes(self.routes)
        self.custom_node_manager.add_routes(self.routes, self.app, nodes.LOADED_MODULE_DIRS.items())
        self.subgraph_manager.add_routes(self.routes, nodes.LOADED_MODULE_DIRS.items())
        self.node_replace_manager.add_routes(self.routes)
        self.app.add_subapp('/internal', self.internal_routes.get_app())
        api_routes = web.RouteTableDef()
        for route in self.routes:
            if isinstance(route, web.RouteDef):
                api_routes.route(route.method, '/api' + route.path)(route.handler, **route.kwargs)
        self.app.add_routes(api_routes)
        self.app.add_routes(self.routes)
        for (name, dir) in nodes.EXTENSION_WEB_DIRS.items():
            self.app.add_routes([web.static('/extensions/' + name, dir)])
        installed_templates_version = FrontendManager.get_installed_templates_version()
        use_legacy_templates = True
        if installed_templates_version:
            try:
                use_legacy_templates = parse_version(installed_templates_version) < parse_version('0.3.0')
            except Exception as exc:
                logging.warning("Unable to parse templates version '%s': %s", installed_templates_version, exc)
        if use_legacy_templates:
            workflow_templates_path = FrontendManager.legacy_templates_path()
            if workflow_templates_path:
                self.app.add_routes([web.static('/templates', workflow_templates_path)])
        else:
            handler = FrontendManager.template_asset_handler()
            if handler:
                self.app.router.add_get('/templates/{path:.*}', handler)
        embedded_docs_path = FrontendManager.embedded_docs_path()
        if embedded_docs_path:
            self.app.add_routes([web.static('/docs', embedded_docs_path)])
        self.app.add_routes([web.static('/', self.web_root)])

    def get_queue_info(self):
        prompt_info = {}
        exec_info = {}
        exec_info['queue_remaining'] = self.prompt_queue.get_tasks_remaining()
        prompt_info['exec_info'] = exec_info
        return prompt_info

    async def send(self, event, data, sid=None):
        if event == BinaryEventTypes.UNENCODED_PREVIEW_IMAGE:
            await self.send_image(data, sid=sid)
        elif event == BinaryEventTypes.PREVIEW_IMAGE_WITH_METADATA:
            (preview_image, metadata) = data
            await self.send_image_with_metadata(preview_image, metadata, sid=sid)
        elif isinstance(data, (bytes, bytearray)):
            await self.send_bytes(event, data, sid)
        else:
            await self.send_json(event, data, sid)

    def encode_bytes(self, event, data):
        if not isinstance(event, int):
            raise RuntimeError(f'Binary event types must be integers, got {event}')
        packed = struct.pack('>I', event)
        message = bytearray(packed)
        message.extend(data)
        return message

    async def send_image(self, image_data, sid=None):
        image_type = image_data[0]
        image = image_data[1]
        max_size = image_data[2]
        if max_size is not None:
            if hasattr(Image, 'Resampling'):
                resampling = Image.Resampling.BILINEAR
            else:
                resampling = Image.Resampling.LANCZOS
            image = ImageOps.contain(image, (max_size, max_size), resampling)
        type_num = 1
        if image_type == 'JPEG':
            type_num = 1
        elif image_type == 'PNG':
            type_num = 2
        bytesIO = BytesIO()
        header = struct.pack('>I', type_num)
        bytesIO.write(header)
        image.save(bytesIO, format=image_type, quality=95, compress_level=1)
        preview_bytes = bytesIO.getvalue()
        await self.send_bytes(BinaryEventTypes.PREVIEW_IMAGE, preview_bytes, sid=sid)

    async def send_image_with_metadata(self, image_data, metadata=None, sid=None):
        image_type = image_data[0]
        image = image_data[1]
        max_size = image_data[2]
        if max_size is not None:
            if hasattr(Image, 'Resampling'):
                resampling = Image.Resampling.BILINEAR
            else:
                resampling = Image.Resampling.LANCZOS
            image = ImageOps.contain(image, (max_size, max_size), resampling)
        mimetype = 'image/png' if image_type == 'PNG' else 'image/jpeg'
        if metadata is None:
            metadata = {}
        metadata['image_type'] = mimetype
        import json
        metadata_json = json.dumps(metadata).encode('utf-8')
        metadata_length = len(metadata_json)
        bytesIO = BytesIO()
        image.save(bytesIO, format=image_type, quality=95, compress_level=1)
        image_bytes = bytesIO.getvalue()
        combined_data = bytearray()
        combined_data.extend(struct.pack('>I', metadata_length))
        combined_data.extend(metadata_json)
        combined_data.extend(image_bytes)
        await self.send_bytes(BinaryEventTypes.PREVIEW_IMAGE_WITH_METADATA, combined_data, sid=sid)

    async def send_bytes(self, event, data, sid=None):
        message = self.encode_bytes(event, data)
        if sid is None:
            sockets = list(self.sockets.values())
            for ws in sockets:
                await send_socket_catch_exception(ws.send_bytes, message)
        elif sid in self.sockets:
            await send_socket_catch_exception(self.sockets[sid].send_bytes, message)

    async def send_json(self, event, data, sid=None):
        message = {'type': event, 'data': data}
        if sid is None:
            sockets = list(self.sockets.values())
            for ws in sockets:
                await send_socket_catch_exception(ws.send_json, message)
        elif sid in self.sockets:
            await send_socket_catch_exception(self.sockets[sid].send_json, message)

    def send_sync(self, event, data, sid=None):
        self.loop.call_soon_threadsafe(self.messages.put_nowait, (event, data, sid))

    def queue_updated(self):
        self.send_sync('status', {'status': self.get_queue_info()})

    async def publish_loop(self):
        while True:
            msg = await self.messages.get()
            await self.send(*msg)

    async def start(self, address, port, verbose=True, call_on_start=None):
        await self.start_multi_address([(address, port)], call_on_start=call_on_start)

    async def start_multi_address(self, addresses, call_on_start=None, verbose=True):
        runner = web.AppRunner(self.app, access_log=None)
        await runner.setup()
        ssl_ctx = None
        scheme = 'http'
        if args.tls_keyfile and args.tls_certfile:
            ssl_ctx = ssl.SSLContext(protocol=ssl.PROTOCOL_TLS_SERVER, verify_mode=ssl.CERT_NONE)
            ssl_ctx.load_cert_chain(certfile=args.tls_certfile, keyfile=args.tls_keyfile)
            scheme = 'https'
        if verbose:
            logging.info('Starting server\n')
        for addr in addresses:
            address = addr[0]
            port = addr[1]
            site = web.TCPSite(runner, address, port, ssl_context=ssl_ctx)
            await site.start()
            if not hasattr(self, 'address'):
                self.address = address
                self.port = port
            if ':' in address:
                address_print = '[{}]'.format(address)
            else:
                address_print = address
            if verbose:
                logging.info('To see the GUI go to: {}://{}:{}'.format(scheme, address_print, port))
        if call_on_start is not None:
            call_on_start(scheme, self.address, self.port)

    def add_on_prompt_handler(self, handler):
        self.on_prompt_handlers.append(handler)

    def trigger_on_prompt(self, json_data):
        for handler in self.on_prompt_handlers:
            try:
                json_data = handler(json_data)
            except Exception:
                logging.warning('[ERROR] An error occurred during the on_prompt_handler processing')
                logging.warning(traceback.format_exc())
        return json_data

    def send_progress_text(self, text: Union[bytes, bytearray, str], node_id: str, sid=None):
        if isinstance(text, str):
            text = text.encode('utf-8')
        node_id_bytes = str(node_id).encode('utf-8')
        message = struct.pack('>I', len(node_id_bytes)) + node_id_bytes + text
        self.send_sync(BinaryEventTypes.TEXT, message, sid)

