    self.model_file_manager = ModelFileManager()
    self.custom_node_manager = CustomNodeManager()
    self.subgraph_manager = SubgraphManager()
    self.node_replace_manager = NodeReplaceManager()
    self.internal_routes = InternalRoutes(self)
    self.supports = ['custom_nodes_from_web']
    self.prompt_queue = execution.PromptQueue(self)
    self.loop = loop
    self.messages = asyncio.Queue()
    self.client_session: Optional[aiohttp.ClientSession] = None
    self.number = 0
    middlewares = [cache_control, deprecation_warning]
    if args.enable_compress_response_body:
        middlewares.append(compress_body)
    if args.enable_cors_header:
        middlewares.append(create_cors_middleware(args.enable_cors_header))
    else:
        middlewares.append(create_origin_only_middleware())
    if args.disable_api_nodes:
        middlewares.append(create_block_external_middleware())
    if args.enable_manager:
        middlewares.append(comfyui_manager.create_middleware())
    max_upload_size = round(args.max_upload_size * 1024 * 1024)
    self.app = web.Application(client_max_size=max_upload_size, middlewares=middlewares)
    self.sockets = dict()
    self.sockets_metadata = dict()
    self.web_root = FrontendManager.init_frontend(args.front_end_version) if args.front_end_root is None else args.front_end_root
    logging.info(f'[Prompt Server] web root: {self.web_root}')
    register_assets_system(self.app, self.user_manager)
    routes = web.RouteTableDef()
    self.routes = routes
    self.last_node_id = None
    self.client_id = None
    self.on_prompt_handlers = []

    @routes.get('/ws')
    async def websocket_handler(request):
        ws = web.WebSocketResponse()
        await ws.prepare(request)
        sid = request.rel_url.query.get('clientId', '')
        if sid:
            self.sockets.pop(sid, None)
        else:
            sid = uuid.uuid4().hex
        self.sockets[sid] = ws
        self.sockets_metadata[sid] = {'feature_flags': {}}
        try:
            await self.send('status', {'status': self.get_queue_info(), 'sid': sid}, sid)
            if self.client_id == sid and self.last_node_id is not None:
                await self.send('executing', {'node': self.last_node_id}, sid)
            first_message = True
            async for msg in ws:
                if msg.type == aiohttp.WSMsgType.ERROR:
                    logging.warning('ws connection closed with exception %s' % ws.exception())
                elif msg.type == aiohttp.WSMsgType.TEXT:
                    try:
                        data = json.loads(msg.data)
                        if first_message and data.get('type') == 'feature_flags':
                            client_flags = data.get('data', {})
                            self.sockets_metadata[sid]['feature_flags'] = client_flags
                            await self.send('feature_flags', feature_flags.get_server_features(), sid)
                            logging.debug(f'Feature flags negotiated for client {sid}: {client_flags}')
                        first_message = False
                    except json.JSONDecodeError:
                        logging.warning(f'Invalid JSON received from client {sid}: {msg.data}')
                    except Exception as e:
                        logging.error(f'Error processing WebSocket message: {e}')
        finally:
            self.sockets.pop(sid, None)
            self.sockets_metadata.pop(sid, None)
        return ws

    @routes.get('/')
    async def get_root(request):
        response = web.FileResponse(os.path.join(self.web_root, 'index.html'))
        response.headers['Cache-Control'] = 'no-cache'
        response.headers['Pragma'] = 'no-cache'
        response.headers['Expires'] = '0'
        return response

    @routes.get('/embeddings')
