        return web.json_response(extensions)

    def get_dir_by_type(dir_type):
        if dir_type is None:
            dir_type = 'input'
        if dir_type == 'input':
            type_dir = folder_paths.get_input_directory()
        elif dir_type == 'temp':
            type_dir = folder_paths.get_temp_directory()
        elif dir_type == 'output':
            type_dir = folder_paths.get_output_directory()
        return (type_dir, dir_type)

    def compare_image_hash(filepath, image):
        hasher = node_helpers.hasher()
        if os.path.exists(filepath):
            a = hasher()
            b = hasher()
            with open(filepath, 'rb') as f:
                a.update(f.read())
                b.update(image.file.read())
                image.file.seek(0)
            return a.hexdigest() == b.hexdigest()
        return False

    def image_upload(post, image_save_function=None):
        image = post.get('image')
        overwrite = post.get('overwrite')
        image_is_duplicate = False
        image_upload_type = post.get('type')
        (upload_dir, image_upload_type) = get_dir_by_type(image_upload_type)
        if image and image.file:
            filename = image.filename
            if not filename:
                return web.Response(status=400)
            subfolder = post.get('subfolder', '')
            full_output_folder = os.path.join(upload_dir, os.path.normpath(subfolder))
            filepath = os.path.abspath(os.path.join(full_output_folder, filename))
            if os.path.commonpath((upload_dir, filepath)) != upload_dir:
                return web.Response(status=400)
            if not os.path.exists(full_output_folder):
                os.makedirs(full_output_folder)
            split = os.path.splitext(filename)
            if overwrite is not None and (overwrite == 'true' or overwrite == '1'):
                pass
            else:
                i = 1
                while os.path.exists(filepath):
                    if compare_image_hash(filepath, image):
                        image_is_duplicate = True
                        break
                    filename = f'{split[0]} ({i}){split[1]}'
                    filepath = os.path.join(full_output_folder, filename)
                    i += 1
            if not image_is_duplicate:
                if image_save_function is not None:
                    image_save_function(image, post, filepath)
                else:
                    with open(filepath, 'wb') as f:
                        f.write(image.file.read())
            return web.json_response({'name': filename, 'subfolder': subfolder, 'type': image_upload_type})
        else:
            return web.Response(status=400)

    @routes.post('/upload/image')
    async def upload_image(request):
        post = await request.post()
        return image_upload(post)

    @routes.post('/upload/mask')
    async def upload_mask(request):
        post = await request.post()

        def image_save_function(image, post, filepath):
            original_ref = json.loads(post.get('original_ref'))
            (filename, output_dir) = folder_paths.annotated_filepath(original_ref['filename'])
            if not filename:
                return web.Response(status=400)
            if filename[0] == '/' or '..' in filename:
                return web.Response(status=400)
            if output_dir is None:
                type = original_ref.get('type', 'output')
                output_dir = folder_paths.get_directory_by_type(type)
            if output_dir is None:
                return web.Response(status=400)
            if original_ref.get('subfolder', '') != '':
                full_output_dir = os.path.join(output_dir, original_ref['subfolder'])
                if os.path.commonpath((os.path.abspath(full_output_dir), output_dir)) != output_dir:
                    return web.Response(status=403)
                output_dir = full_output_dir
            file = os.path.join(output_dir, filename)
            if os.path.isfile(file):
                with Image.open(file) as original_pil:
                    metadata = PngInfo()
                    if hasattr(original_pil, 'text'):
                        for key in original_pil.text:
                            metadata.add_text(key, original_pil.text[key])
                    original_pil = original_pil.convert('RGBA')
                    mask_pil = Image.open(image.file).convert('RGBA')
                    new_alpha = mask_pil.getchannel('A')
                    original_pil.putalpha(new_alpha)
                    original_pil.save(filepath, compress_level=4, pnginfo=metadata)
        return image_upload(post, image_save_function)

    @routes.get('/view')
    async def view_image(request):
        if 'filename' in request.rel_url.query:
            filename = request.rel_url.query['filename']
            (filename, output_dir) = folder_paths.annotated_filepath(filename)
            if not filename:
                return web.Response(status=400)
            if filename[0] == '/' or '..' in filename:
                return web.Response(status=400)
            if output_dir is None:
                type = request.rel_url.query.get('type', 'output')
                output_dir = folder_paths.get_directory_by_type(type)
            if output_dir is None:
                return web.Response(status=400)
            if 'subfolder' in request.rel_url.query:
                full_output_dir = os.path.join(output_dir, request.rel_url.query['subfolder'])
                if os.path.commonpath((os.path.abspath(full_output_dir), output_dir)) != output_dir:
                    return web.Response(status=403)
                output_dir = full_output_dir
            filename = os.path.basename(filename)
            file = os.path.join(output_dir, filename)
            if os.path.isfile(file):
                if 'preview' in request.rel_url.query:
                    with Image.open(file) as img:
                        preview_info = request.rel_url.query['preview'].split(';')
                        image_format = preview_info[0]
                        if image_format not in ['webp', 'jpeg'] or 'a' in request.rel_url.query.get('channel', ''):
                            image_format = 'webp'
                        quality = 90
                        if preview_info[-1].isdigit():
                            quality = int(preview_info[-1])
                        buffer = BytesIO()
                        if image_format in ['jpeg'] or request.rel_url.query.get('channel', '') == 'rgb':
                            img = img.convert('RGB')
                        img.save(buffer, format=image_format, quality=quality)
                        buffer.seek(0)
                        return web.Response(body=buffer.read(), content_type=f'image/{image_format}', headers={'Content-Disposition': f'filename="{filename}"'})
                if 'channel' not in request.rel_url.query:
                    channel = 'rgba'
                else:
                    channel = request.rel_url.query['channel']
                if channel == 'rgb':
                    with Image.open(file) as img:
                        if img.mode == 'RGBA':
                            (r, g, b, a) = img.split()
                            new_img = Image.merge('RGB', (r, g, b))
                        else:
                            new_img = img.convert('RGB')
                        buffer = BytesIO()
                        new_img.save(buffer, format='PNG')
                        buffer.seek(0)
                        return web.Response(body=buffer.read(), content_type='image/png', headers={'Content-Disposition': f'filename="{filename}"'})
                elif channel == 'a':
                    with Image.open(file) as img:
                        if img.mode == 'RGBA':
                            (_, _, _, a) = img.split()
                        else:
                            a = Image.new('L', img.size, 255)
                        alpha_img = Image.new('RGBA', img.size)
                        alpha_img.putalpha(a)
                        alpha_buffer = BytesIO()
                        alpha_img.save(alpha_buffer, format='PNG')
                        alpha_buffer.seek(0)
                        return web.Response(body=alpha_buffer.read(), content_type='image/png', headers={'Content-Disposition': f'filename="{filename}"'})
                else:
                    content_type = mimetypes.guess_type(filename)[0] or 'application/octet-stream'
                    if content_type in {'text/html', 'text/html-sandboxed', 'application/xhtml+xml', 'text/javascript', 'text/css'}:
                        content_type = 'application/octet-stream'
                    return web.FileResponse(file, headers={'Content-Disposition': f'filename="{filename}"', 'Content-Type': content_type})
        return web.Response(status=404)

    @routes.get('/view_metadata/{folder_name}')
    async def view_metadata(request):
        folder_name = request.match_info.get('folder_name', None)
        if folder_name is None:
            return web.Response(status=404)
        if 'filename' not in request.rel_url.query:
            return web.Response(status=404)
        filename = request.rel_url.query['filename']
        if not filename.endswith('.safetensors'):
            return web.Response(status=404)
        safetensors_path = folder_paths.get_full_path(folder_name, filename)
        if safetensors_path is None:
            return web.Response(status=404)
        out = comfy.utils.safetensors_header(safetensors_path, max_size=1024 * 1024)
        if out is None:
            return web.Response(status=404)
        dt = json.loads(out)
        if '__metadata__' not in dt:
            return web.Response(status=404)
        return web.json_response(dt['__metadata__'])

