        return web.Response(status=200)

async def setup(self):
    timeout = aiohttp.ClientTimeout(total=None)
    self.client_session = aiohttp.ClientSession(timeout=timeout)

def add_routes(self):
    self.user_manager.add_routes(self.routes)
    self.model_file_manager.add_routes(self.routes)
    self.custom_node_manager.add_routes(self.routes, self.app, nodes.LOADED_MODULE_DIRS.items())
    self.subgraph_manager.add_routes(self.routes, nodes.LOADED_MODULE_DIRS.items())
    self.node_replace_manager.add_routes(self.routes)
    self.app.add_subapp('/internal', self.internal_routes.get_app())
    api_routes = web.RouteTableDef()
    for route in self.routes:
        if isinstance(route, web.RouteDef):
            api_routes.route(route.method, '/api' + route.path)(route.handler, **route.kwargs)
    self.app.add_routes(api_routes)
    self.app.add_routes(self.routes)
    for (name, dir) in nodes.EXTENSION_WEB_DIRS.items():
        self.app.add_routes([web.static('/extensions/' + name, dir)])
    installed_templates_version = FrontendManager.get_installed_templates_version()
    use_legacy_templates = True
    if installed_templates_version:
        try:
            use_legacy_templates = parse_version(installed_templates_version) < parse_version('0.3.0')
        except Exception as exc:
            logging.warning("Unable to parse templates version '%s': %s", installed_templates_version, exc)
    if use_legacy_templates:
        workflow_templates_path = FrontendManager.legacy_templates_path()
        if workflow_templates_path:
            self.app.add_routes([web.static('/templates', workflow_templates_path)])
    else:
        handler = FrontendManager.template_asset_handler()
        if handler:
            self.app.router.add_get('/templates/{path:.*}', handler)
    embedded_docs_path = FrontendManager.embedded_docs_path()
    if embedded_docs_path:
        self.app.add_routes([web.static('/docs', embedded_docs_path)])
    self.app.add_routes([web.static('/', self.web_root)])

def get_queue_info(self):
    prompt_info = {}
    exec_info = {}
    exec_info['queue_remaining'] = self.prompt_queue.get_tasks_remaining()
    prompt_info['exec_info'] = exec_info
    return prompt_info

async def send(self, event, data, sid=None):
    if event == BinaryEventTypes.UNENCODED_PREVIEW_IMAGE:
        await self.send_image(data, sid=sid)
    elif event == BinaryEventTypes.PREVIEW_IMAGE_WITH_METADATA:
        (preview_image, metadata) = data
        await self.send_image_with_metadata(preview_image, metadata, sid=sid)
    elif isinstance(data, (bytes, bytearray)):
        await self.send_bytes(event, data, sid)
    else:
        await self.send_json(event, data, sid)

def encode_bytes(self, event, data):
    if not isinstance(event, int):
        raise RuntimeError(f'Binary event types must be integers, got {event}')
    packed = struct.pack('>I', event)
    message = bytearray(packed)
    message.extend(data)
    return message

async def send_image(self, image_data, sid=None):
    image_type = image_data[0]
    image = image_data[1]
    max_size = image_data[2]
    if max_size is not None:
        if hasattr(Image, 'Resampling'):
            resampling = Image.Resampling.BILINEAR
        else:
            resampling = Image.Resampling.LANCZOS
        image = ImageOps.contain(image, (max_size, max_size), resampling)
    type_num = 1
    if image_type == 'JPEG':
        type_num = 1
    elif image_type == 'PNG':
        type_num = 2
    bytesIO = BytesIO()
    header = struct.pack('>I', type_num)
    bytesIO.write(header)
    image.save(bytesIO, format=image_type, quality=95, compress_level=1)
    preview_bytes = bytesIO.getvalue()
    await self.send_bytes(BinaryEventTypes.PREVIEW_IMAGE, preview_bytes, sid=sid)

async def send_image_with_metadata(self, image_data, metadata=None, sid=None):
    image_type = image_data[0]
    image = image_data[1]
    max_size = image_data[2]
    if max_size is not None:
        if hasattr(Image, 'Resampling'):
            resampling = Image.Resampling.BILINEAR
        else:
            resampling = Image.Resampling.LANCZOS
        image = ImageOps.contain(image, (max_size, max_size), resampling)
    mimetype = 'image/png' if image_type == 'PNG' else 'image/jpeg'
    if metadata is None:
        metadata = {}
    metadata['image_type'] = mimetype
    import json
    metadata_json = json.dumps(metadata).encode('utf-8')
    metadata_length = len(metadata_json)
    bytesIO = BytesIO()
    image.save(bytesIO, format=image_type, quality=95, compress_level=1)
    image_bytes = bytesIO.getvalue()
    combined_data = bytearray()
    combined_data.extend(struct.pack('>I', metadata_length))
    combined_data.extend(metadata_json)
    combined_data.extend(image_bytes)
    await self.send_bytes(BinaryEventTypes.PREVIEW_IMAGE_WITH_METADATA, combined_data, sid=sid)

async def send_bytes(self, event, data, sid=None):
    message = self.encode_bytes(event, data)
    if sid is None:
        sockets = list(self.sockets.values())
        for ws in sockets:
            await send_socket_catch_exception(ws.send_bytes, message)
    elif sid in self.sockets:
        await send_socket_catch_exception(self.sockets[sid].send_bytes, message)

async def send_json(self, event, data, sid=None):
    message = {'type': event, 'data': data}
    if sid is None:
        sockets = list(self.sockets.values())
        for ws in sockets:
            await send_socket_catch_exception(ws.send_json, message)
    elif sid in self.sockets:
        await send_socket_catch_exception(self.sockets[sid].send_json, message)

def send_sync(self, event, data, sid=None):
    self.loop.call_soon_threadsafe(self.messages.put_nowait, (event, data, sid))

def queue_updated(self):
    self.send_sync('status', {'status': self.get_queue_info()})

async def publish_loop(self):
    while True:
        msg = await self.messages.get()
        await self.send(*msg)

async def start(self, address, port, verbose=True, call_on_start=None):
    await self.start_multi_address([(address, port)], call_on_start=call_on_start)

async def start_multi_address(self, addresses, call_on_start=None, verbose=True):
    runner = web.AppRunner(self.app, access_log=None)
    await runner.setup()
    ssl_ctx = None
    scheme = 'http'
    if args.tls_keyfile and args.tls_certfile:
        ssl_ctx = ssl.SSLContext(protocol=ssl.PROTOCOL_TLS_SERVER, verify_mode=ssl.CERT_NONE)
        ssl_ctx.load_cert_chain(certfile=args.tls_certfile, keyfile=args.tls_keyfile)
        scheme = 'https'
    if verbose:
        logging.info('Starting server\n')
    for addr in addresses:
        address = addr[0]
        port = addr[1]
        site = web.TCPSite(runner, address, port, ssl_context=ssl_ctx)
        await site.start()
        if not hasattr(self, 'address'):
            self.address = address
            self.port = port
        if ':' in address:
            address_print = '[{}]'.format(address)
        else:
            address_print = address
        if verbose:
            logging.info('To see the GUI go to: {}://{}:{}'.format(scheme, address_print, port))
    if call_on_start is not None:
        call_on_start(scheme, self.address, self.port)

def add_on_prompt_handler(self, handler):
    self.on_prompt_handlers.append(handler)

def trigger_on_prompt(self, json_data):
    for handler in self.on_prompt_handlers:
        try:
            json_data = handler(json_data)
        except Exception:
            logging.warning('[ERROR] An error occurred during the on_prompt_handler processing')
            logging.warning(traceback.format_exc())
    return json_data

def send_progress_text(self, text: Union[bytes, bytearray, str], node_id: str, sid=None):
    if isinstance(text, str):
        text = text.encode('utf-8')
    node_id_bytes = str(node_id).encode('utf-8')
    message = struct.pack('>I', len(node_id_bytes)) + node_id_bytes + text
    self.send_sync(BinaryEventTypes.TEXT, message, sid)

