                    else:
                        self.console.print(f'[color(160)]...Weight [bold]{inner_path}[/] present in {ref_name}, missing from {target_name}[/]')
                elif isinstance(ref_val, dict):
                    (_error_count, _match_count) = _compare(target[ref_key], ref_spec[ref_key], inner_path, target_name, ref_name, error_count=error_count, match_count=match_count, checked_paths=checked_paths)
                    error_count += _error_count
                    match_count += _match_count
                elif target[ref_key].shape != ref_val.shape:
                    error_count += 1
                    checked_paths.add(inner_path)
                    self.console.print(f'[color(160)]...Weight shape mismatch for [bold]{inner_path}[/][/]\n    In {ref_name}: shape={ref_val.shape}\n    In {target_name}: shape={target[ref_key].shape}')
                else:
                    match_count += 1
            return (error_count, match_count)
        checked_paths = set()
        (error_count, match_count) = _compare(self.weights_dict, ref_spec, inner_path='', target_name='saved file', ref_name='reference model', error_count=0, match_count=0, checked_paths=checked_paths)
        (_error_count, _) = _compare(ref_spec, self.weights_dict, inner_path='', target_name='reference model', ref_name='saved file', error_count=0, match_count=0, checked_paths=checked_paths)
        error_count += _error_count
        self.console.print('─────────────────────')
