    def _edit_object(self, edit_fn, source_name, target_name=None):
        if target_name is not None and '/' in target_name:
            raise ValueError(f"Argument `target_name` should be a leaf name, not a full path name. Received: target_name='{target_name}'")
        if '/' in source_name:
            elements = source_name.split('/')
