        self._edit_object(add_weight_fn, object_name)

    def save(self, filepath):
        """Save the edited weights file.

        Args:
            filepath: Path to save the file to.
                Must be a `.weights.h5` file.
        """
        filepath = str(filepath)
        if not filepath.endswith('.weights.h5'):
            raise ValueError(f'Invalid `filepath` argument: expected a `.weights.h5` extension. Received: filepath={filepath}')
        weights_store = H5IOStore(filepath, mode='w')

        def _save(weights_dict, weights_store, inner_path):
            vars_to_create = {}
            for (name, value) in weights_dict.items():
                if isinstance(value, dict):
                    if value:
                        _save(weights_dict[name], weights_store, inner_path=os.path.join(inner_path, name))
                else:
                    vars_to_create[name] = value
            if vars_to_create:
                var_store = weights_store.make(inner_path)
                for (name, value) in vars_to_create.items():
                    var_store[name] = value
        _save(self.weights_dict, weights_store, inner_path='')
        weights_store.close()

    def resave_weights(self, filepath):
        self.save(filepath)

    def _extract_weights_from_store(self, data, metadata=None, inner_path=''):
        metadata = metadata or {}
        object_metadata = {}
        for (k, v) in data.attrs.items():
            object_metadata[k] = v
        if object_metadata:
            metadata[inner_path] = object_metadata
        result = collections.OrderedDict()
        for key in data.keys():
            current_inner_path = f'{inner_path}/{key}'
            value = data[key]
            if isinstance(value, h5py.Group):
                if len(value) == 0:
                    continue
                if 'vars' in value.keys() and len(value['vars']) == 0:
                    continue
                if 'vars' in value.keys():
                    (result[key], metadata) = self._extract_weights_from_store(value['vars'], metadata=metadata, inner_path=current_inner_path)
                else:
                    (result[key], metadata) = self._extract_weights_from_store(value, metadata=metadata, inner_path=current_inner_path)
                continue
            if not isinstance(value, h5py.Dataset):
                continue
            if value.external:
                raise ValueError(f'Not allowed: H5 file Dataset with external links: {value.external}')
            shape = value.shape
            dtype = value.dtype
            if any((dim < 0 for dim in shape)):
                raise ValueError('Malformed HDF5 dataset shape encountered in .keras file; negative dimension detected.')
            if len(shape) > 64:
                raise ValueError('Malformed HDF5 dataset shape encountered in .keras file; tensor rank exceeds safety limit.')
            num_elems = int(np.prod(shape))
            MAX_BYTES = 1 << 32
            size_bytes = num_elems * dtype.itemsize
            if size_bytes > MAX_BYTES:
                raise ValueError(f'HDF5 dataset too large to load safely ({size_bytes} bytes; limit is {MAX_BYTES}).')
            result[key] = value[()]
        return (result, metadata)

    def _generate_filepath_info(self, rich_style=False):
        if rich_style:
            filepath = f"'{self.filepath}'"
            filepath = f'{summary_utils.highlight_symbol(filepath)}'
        else:
            filepath = f"'{self.filepath}'"
        return f'Keras model file {filepath}'

    def _generate_config_info(self, rich_style=False):
        return pprint.pformat(self.config)

    def _generate_metadata_info(self, rich_style=False):
        version = self.metadata['keras_version']
        date = self.metadata['date_saved']
        if rich_style:
            version = f'{summary_utils.highlight_symbol(version)}'
            date = f'{summary_utils.highlight_symbol(date)}'
        return f'Saved with Keras {version} - date: {date}'

    def _print_weights_structure(self, weights_dict, indent=0, is_first=True, prefix='', inner_path=''):
        for (idx, (key, value)) in enumerate(weights_dict.items()):
            inner_path = os.path.join(inner_path, key)
            is_last = idx == len(weights_dict) - 1
            if is_first:
                is_first = False
                connector = '> '
            elif is_last:
                connector = '└─ '
            else:
                connector = '├─ '
            if isinstance(value, dict):
                bold_key = summary_utils.bold_text(key)
                object_label = f'{prefix}{connector}{bold_key}'
                if inner_path in self.object_metadata:
                    metadata = self.object_metadata[inner_path]
                    if 'name' in metadata:
                        name = metadata['name']
                        object_label += f" ('{name}')"
                self.console.print(object_label)
                if is_last:
                    appended = '    '
                else:
                    appended = '│   '
                new_prefix = prefix + appended
                self._print_weights_structure(value, indent + 1, is_first=is_first, prefix=new_prefix, inner_path=inner_path)
            elif hasattr(value, 'shape'):
                bold_key = summary_utils.bold_text(key)
                self.console.print(f'{prefix}{connector}{bold_key}:' + f' shape={value.shape}, dtype={value.dtype}')
            else:
                self.console.print(f'{prefix}{connector}{key}: {value}')

    def _weights_summary_cli(self):
        self.console.print('Weights structure')
        self._print_weights_structure(self.weights_dict, prefix=' ' * 2)

    def _weights_summary_interactive(self):

        def _generate_html_weights(dictionary, margin_left=0, font_size=1):
            html = ''
            for (key, value) in dictionary.items():
                if isinstance(value, dict) and value:
                    weights_html = _generate_html_weights(value, margin_left + 20, font_size - 1)
                    html += f'<details style="margin-left: {margin_left}px;"><summary style="font-size: {font_size}em; font-weight: bold;">{key}</summary>{weights_html}</details>'
                else:
                    html += f'<details style="margin-left: {margin_left}px;"><summary style="font-size: {font_size}em;">{key} : shape={value.shape}, dtype={value.dtype}</summary><div style="margin-left: {margin_left}px;"margin-top: {margin_left}px;">{display_weight(value)}</div></details>'
            return html
        output = 'Weights structure'
        initialize_id_counter()
        output += _generate_html_weights(self.weights_dict)
        ipython.display.display(ipython.display.HTML(output))

